BEGIN;
CREATE FUNCTION pg_temp.assert(ok boolean,message text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION '%',message; END IF; END $$;
INSERT INTO auth.users(id,email) VALUES('eb000000-0000-4000-8000-000000000001','generation-reconcile@example.invalid');
INSERT INTO public.ai_models(id,provider,provider_model_id,display_name,status,generator_compatible,generator_enabled,quality_check_compatible,quality_check_enabled) VALUES('eb100000-0000-4000-8000-000000000001','openai','reconcile-fixture','Reconcile','enabled',true,true,true,true);
INSERT INTO public.ai_generation_jobs(id,user_id,idempotency_key,status,input_payload) VALUES('eb200000-0000-4000-8000-000000000001','eb000000-0000-4000-8000-000000000001',gen_random_uuid(),'processing','{"operation":"generate","generationModel":"reconcile-fixture"}');
SELECT pg_temp.assert((SELECT model='reconcile-fixture' AND provider='openai' FROM public.ai_generation_jobs WHERE id='eb200000-0000-4000-8000-000000000001'),'Model recorded before dispatch');
SELECT public.begin_ai_execution_internal('eb300000-0000-4000-8000-000000000001','eb000000-0000-4000-8000-000000000001','generate','openai','reconcile-fixture',NULL,'eb200000-0000-4000-8000-000000000001',NULL);
SELECT public.checkpoint_ai_execution_internal('eb300000-0000-4000-8000-000000000001','eb000000-0000-4000-8000-000000000001','{"text":"invalid","stopReason":"end_turn","usage":{"inputTokens":10,"outputTokens":5,"totalTokens":15,"providerReportedCostUsd":0.0001234567890123}}');
UPDATE public.ai_generation_jobs SET status='failed',model=NULL,completed_at=now() WHERE id='eb200000-0000-4000-8000-000000000001';
SELECT pg_temp.assert('accounting_pending'=ANY(public.ai_model_uninstall_reasons((SELECT m FROM public.ai_models m WHERE provider_model_id='reconcile-fixture'))),'Missing final usage blocks');
SELECT pg_temp.assert(NOT public.resolve_failed_generation_internal('eb300000-0000-4000-8000-000000000001','eb000000-0000-4000-8000-000000000001','eb200000-0000-4000-8000-000000000001','{"text":"invalid","stopReason":"end_turn","usage":{"inputTokens":10,"outputTokens":5,"totalTokens":15,"providerReportedCostUsd":0.0001234567890123}}','invalid_response'),'No release without final receipt');
SELECT public.settle_ai_usage_internal('{"id":"eb300000-0000-4000-8000-000000000001","user_id":"eb000000-0000-4000-8000-000000000001","provider":"openai","model":"reconcile-fixture","operation":"generate","provider_usage_state":"final","input_tokens":10,"output_tokens":5,"total_tokens":15,"provider_reported_cost_usd":0.0001234567890123}');
SELECT pg_temp.assert('recovery_pending'=ANY(public.ai_model_uninstall_reasons((SELECT m FROM public.ai_models m WHERE provider_model_id='reconcile-fixture'))),'Observed response still needs validation');
DO $$ DECLARE r jsonb; ok boolean; BEGIN
 SELECT result INTO r FROM public.ai_provider_executions WHERE id='eb300000-0000-4000-8000-000000000001';
 PERFORM pg_temp.assert(NOT public.resolve_failed_generation_internal('eb300000-0000-4000-8000-000000000001',gen_random_uuid(),'eb200000-0000-4000-8000-000000000001',r,'invalid_response'),'Cross-user denied');
 PERFORM pg_temp.assert(NOT public.resolve_failed_generation_internal('eb300000-0000-4000-8000-000000000001','eb000000-0000-4000-8000-000000000001','eb200000-0000-4000-8000-000000000001','{}','invalid_response'),'Stale snapshot denied');
 UPDATE public.ai_generation_jobs SET status='processing' WHERE id='eb200000-0000-4000-8000-000000000001';
 PERFORM pg_temp.assert(NOT public.resolve_failed_generation_internal('eb300000-0000-4000-8000-000000000001','eb000000-0000-4000-8000-000000000001','eb200000-0000-4000-8000-000000000001',r,'invalid_response'),'Active work cannot be reconciled');
 UPDATE public.ai_generation_jobs SET status='failed',cancel_requested_at=now() WHERE id='eb200000-0000-4000-8000-000000000001';
 PERFORM pg_temp.assert(NOT public.resolve_failed_generation_internal('eb300000-0000-4000-8000-000000000001','eb000000-0000-4000-8000-000000000001','eb200000-0000-4000-8000-000000000001',r,'invalid_response'),'Cancellation does not authorize a failure attestation');
 UPDATE public.ai_generation_jobs SET cancel_requested_at=NULL WHERE id='eb200000-0000-4000-8000-000000000001';
 INSERT INTO public.ai_usage_outbox(id,payload) VALUES('eb300000-0000-4000-8000-000000000001','{"id":"eb300000-0000-4000-8000-000000000001","user_id":"eb000000-0000-4000-8000-000000000001","provider":"openai","model":"reconcile-fixture","operation":"generate","provider_usage_state":"final","input_tokens":10,"output_tokens":5,"total_tokens":15,"provider_reported_cost_usd":0.0001234567890123}');
 PERFORM pg_temp.assert(NOT public.resolve_failed_generation_internal('eb300000-0000-4000-8000-000000000001','eb000000-0000-4000-8000-000000000001','eb200000-0000-4000-8000-000000000001',r,'invalid_response'),'Lost-ACK outbox remains protected');
 PERFORM public.flush_ai_usage_outbox(50);
 UPDATE public.global_ai_usage_policy SET enabled=false;
 FOR n IN 1..2 LOOP
  ok:=public.resolve_failed_generation_internal('eb300000-0000-4000-8000-000000000001','eb000000-0000-4000-8000-000000000001','eb200000-0000-4000-8000-000000000001',r,'invalid_response');
  PERFORM pg_temp.assert(ok,'Idempotent final reconciliation');
 END LOOP;
 PERFORM pg_temp.assert((SELECT result=r AND application_recovery_attempts=0 FROM public.ai_provider_executions WHERE id='eb300000-0000-4000-8000-000000000001'),'Result and real recovery count retained');
END $$;
SELECT pg_temp.assert((SELECT model='reconcile-fixture' FROM public.ai_generation_jobs WHERE id='eb200000-0000-4000-8000-000000000001'),'Legacy NULL model repaired from authoritative execution');
SELECT pg_temp.assert((SELECT count(*)=1 FROM public.ai_usage_logs WHERE id='eb300000-0000-4000-8000-000000000001'),'One financial entry');
SELECT pg_temp.assert(cardinality(public.ai_model_uninstall_reasons((SELECT m FROM public.ai_models m WHERE provider_model_id='reconcile-fixture')))=0,'Only proven rejected settled work releases guard');
SELECT pg_temp.assert(NOT has_function_privilege('anon','public.resolve_failed_generation_internal(uuid,uuid,uuid,jsonb,text)','EXECUTE') AND NOT has_function_privilege('authenticated','public.resolve_failed_generation_internal(uuid,uuid,uuid,jsonb,text)','EXECUTE') AND has_function_privilege('service_role','public.resolve_failed_generation_internal(uuid,uuid,uuid,jsonb,text)','EXECUTE'),'Server-only attestation');
UPDATE public.ai_provider_executions SET application_resolution=NULL,application_resolved_at=NULL,application_recovery_attempts=8 WHERE id='eb300000-0000-4000-8000-000000000001';
SELECT pg_temp.assert('recovery_pending'=ANY(public.ai_model_uninstall_reasons((SELECT m FROM public.ai_models m WHERE provider_model_id='reconcile-fixture'))),'Exhaustion is not terminal proof');
SELECT pg_temp.assert(public.claim_failed_generation_validation_internal() @> '[{"job_id":"eb200000-0000-4000-8000-000000000001"}]','Exhausted but settled failure can be checked without provider dispatch');
SELECT pg_temp.assert(public.claim_failed_generation_validation_internal()='[]'::jsonb,'Validation claim is bounded and not concurrently repeated');
SELECT pg_temp.assert((SELECT application_recovery_attempts=8 FROM public.ai_provider_executions WHERE id='eb300000-0000-4000-8000-000000000001'),'Validation does not fake recovery attempts');
UPDATE public.ai_provider_executions SET result=NULL,state='execution_unknown' WHERE id='eb300000-0000-4000-8000-000000000001';
SELECT pg_temp.assert('unresolved_execution'=ANY(public.ai_model_uninstall_reasons((SELECT m FROM public.ai_models m WHERE provider_model_id='reconcile-fixture'))),'Unknown provider state always blocks');
ROLLBACK;
